   seen.add((r,c));q.append((r,c))
while q:
 r,c=q.popleft()
 for dr in (-1,0,1):
  for dc in (-1,0,1):
   rr,cc=r+dr,c+dc
   if 0<=rr<R and 0<=cc<C and grid[rr][cc]==9 and (rr,cc) not in seen:
    seen.add((rr,cc));q.append((rr,cc))
out=[row[:] for row in grid]
inside=[]
for r in range(R):
 for c in range(C):
  if grid[r][c]==9 and (r,c) not in seen:
   out[r][c]=4;inside.append((r,c))
len(inside), inside, [' '.join(map(str,row)) for row in out]
